const P = {"tool": "Scientific Reproducibility Manager", "p": 0.96, "procs": [2, 4, 8, 16, 64]};

function demoMain(P){
  var out=[], ni;
  for(ni=0; ni<P.procs.length; ni++){ var n=P.procs[ni]; var S=1/((1-P.p)+P.p/n); out.push('n='+n+' S='+S.toFixed(2)+' eff='+(S/n*100).toFixed(1)+'%'); }
  return 'Amdahl scaling ('+P.tool+', parallel fraction p='+P.p+'): '+out.join(' | ')+' (theoretical upper bound S_max='+(1/(1-P.p)).toFixed(2)+')';
}
console.log(demoMain(P));

